package com.secure.documentwallet;

import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.util.concurrent.*;

/** Secure, landscape, tap-to-flip viewer opened by holding an ID or bank card. */
public class CardFullscreenActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private VaultRepository repo;private Bitmap front,back;private FrameLayout card;private TextView message;private boolean showingBack,ready;
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!Session.valid()){finish();return;}getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);repo=new VaultRepository(this);build();load();}
 private void build(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff031426);LinearLayout column=Ui.column(this);column.setGravity(Gravity.CENTER);column.setPadding(Ui.dp(this,28),Ui.dp(this,12),Ui.dp(this,28),Ui.dp(this,12));LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView lock=Ui.text(this,"🔒",21,0xffd6ad52);lock.setGravity(Gravity.CENTER);header.addView(lock,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,44)));String heading=getIntent().getStringExtra("title");TextView title=Ui.title(this,heading==null?"Secure Card":heading,20);title.setTextColor(Color.WHITE);title.setGravity(Gravity.CENTER);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView close=Ui.text(this,"×",32,Color.WHITE);close.setGravity(Gravity.CENTER);close.setContentDescription("Close Enlarge Mode");close.setBackground(Ui.bg(0xff16344c,Ui.dp(this,22)));close.setOnClickListener(v->finish());header.addView(close,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,44)));column.addView(header,new LinearLayout.LayoutParams(-1,-2));card=new FrameLayout(this);card.setBackground(Ui.stroke(0xff071f34,Ui.dp(this,1),0xff5ac6b7,Ui.dp(this,22)));card.setClipToOutline(true);card.setElevation(Ui.dp(this,14));card.setCameraDistance(Ui.dp(this,9000));card.setOnClickListener(v->flip());ProgressBar loading=new ProgressBar(this);card.addView(loading,new FrameLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48),Gravity.CENTER));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,0,1);cp.setMargins(Ui.dp(this,34),Ui.dp(this,8),Ui.dp(this,34),Ui.dp(this,6));column.addView(card,cp);message=Ui.text(this,"Tap To Flip  ·  Press × To Close",13,0xffb8d8cf);message.setGravity(Gravity.CENTER);column.addView(message,new LinearLayout.LayoutParams(-1,-2));root.addView(column,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
 private void load(){String id=getIntent().getStringExtra("id");int initialPage=Math.max(0,getIntent().getIntExtra("page",0));io.execute(()->{try{JSONArray all=repo.all();JSONObject found=null;for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&id.equals(item.optString("id"))){found=item;break;}}if(found==null)throw new IllegalStateException("Card Not Found");JSONArray pages=found.optJSONArray("pages");if(pages==null||pages.length()==0)throw new IllegalStateException("No Card Image Was Saved");Bitmap first=decode(repo.page(found,0)),second=pages.length()>1?decode(repo.page(found,1)):null;runOnUiThread(()->{if(isFinishing()){recycle(first);recycle(second);return;}front=first;back=second;showingBack=initialPage==1&&back!=null;ready=true;showSide(false);});}catch(Exception error){runOnUiThread(()->showError(error.getMessage()));}});}
 private Bitmap decode(byte[] raw){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>2600)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;return BitmapFactory.decodeByteArray(raw,0,raw.length,options);}
 private void showSide(boolean animate){card.removeAllViews();Bitmap image=showingBack?back:front;if(image!=null){ImageView view=new ImageView(this);view.setImageBitmap(image);view.setScaleType(ImageView.ScaleType.FIT_CENTER);view.setBackgroundColor(0xff031426);card.addView(view,new FrameLayout.LayoutParams(-1,-1));}TextView badge=Ui.text(this,showingBack?"BACK":"FRONT",11,Color.WHITE);badge.setTypeface(null,android.graphics.Typeface.BOLD);badge.setGravity(Gravity.CENTER);badge.setBackground(Ui.bg(0xdd0b8179,Ui.dp(this,12)));FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,27),Gravity.TOP|Gravity.END);bp.setMargins(0,Ui.dp(this,12),Ui.dp(this,12),0);card.addView(badge,bp);message.setText((back==null?"No Back Image Saved  ·  ":"Tap To Flip  ·  ")+"Press × To Close");if(animate){card.setRotationY(-90);card.animate().rotationY(0).setDuration(145).start();}else{card.setAlpha(0);card.setScaleX(.88f);card.setScaleY(.88f);card.animate().alpha(1).scaleX(1).scaleY(1).setDuration(190).start();}}
 private void flip(){if(!ready)return;if(back==null){card.animate().scaleX(.975f).scaleY(.975f).setDuration(60).withEndAction(()->card.animate().scaleX(1).scaleY(1).setDuration(80).start()).start();return;}ready=false;card.animate().rotationY(90).setDuration(125).withEndAction(()->{showingBack=!showingBack;showSide(true);card.animate().setDuration(145).withEndAction(()->ready=true).start();}).start();}
 private void showError(String detail){card.removeAllViews();TextView error=Ui.text(this,detail==null?"Could Not Open This Card":detail,16,0xffffb4ab);error.setGravity(Gravity.CENTER);card.addView(error,new FrameLayout.LayoutParams(-1,-1));message.setText("Press × To Close");}
 private void recycle(Bitmap bitmap){if(bitmap!=null&&!bitmap.isRecycled())bitmap.recycle();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();recycle(front);recycle(back);}
}
